import {TriangleDownIcon, XIcon} from '@primer/octicons-react'
import {ActionList, AnchoredOverlay, Button, Dialog, Heading, IconButton} from '@primer/react'
import React, {forwardRef, useEffect, useId, useRef, useState} from 'react'

import styles from './SimpleSelect.module.css'
import type {FooterButtons, Items, SelectItemProps, SelectProps, SimpleSelectDialogProps} from './types'

export function SimpleSelect({
  variant = 'overlay',
  items,
  label,
  title = 'Select an item',
  selectionVariant,
  onSelect,
  renderText,
  onSave,
  onCancel,
  selectable,
  buttonProps,
  outsideClick = 'save',
  onEscape = 'save',
  focusTarget = 'first-target',
  dialogProps,
  footerButtons,
}: SelectProps) {
  const [open, setOpen] = useState(false)
  const [staticItems, setStaticItems] = useState<Items[]>()
  const [selectItems, setSelectItems] = useState<Items[]>([])

  const firstItem = useRef<HTMLLIElement>(null)
  const headingId = useId()
  const selectedItems = selectable ? selectItems : items.filter(item => item.selected)

  const btn = useRef<HTMLButtonElement>(null)

  if (!staticItems) {
    setStaticItems(items)
    setSelectItems(items.filter(item => item.selected))
  }

  const handleAction = (action: 'save' | 'cancel', received?: Items[]) => {
    if (action === 'save' && (onSave || selectable)) {
      const currentItems = selectable ? received || selectItems : items.filter(item => item.selected)
      // TODO: Improve, we shouldn't need to iterate through all items here
      const updatedItems = items.map(item => {
        const isSelected = currentItems.find(selectedItem => selectedItem.id === item.id)
        return isSelected ? {...item, selected: true} : {...item, selected: false}
      })

      setStaticItems(updatedItems)
      if (onSave) onSave(updatedItems)
    } else if (action === 'cancel' && onCancel) {
      onCancel(staticItems || items)
    } else if (action === 'cancel' && selectable) {
      setSelectItems(staticItems?.filter(item => item.selected) || [])
    }
    setOpen(false)
  }

  const selectSave = () => handleAction('save')
  const selectCancel = () => handleAction('cancel')

  const handleControlledItems = (selection: Items[]) => {
    setSelectItems(selection)

    if (selectItems) selectable?.(selection)
    if (selectionVariant === 'single') {
      handleAction('save', selection)
    }
  }

  const onClose = (gesture: string) => {
    if (gesture === 'click-outside' || gesture === 'anchor-click' || gesture === 'close-button') {
      handleAction(outsideClick)
    } else if (gesture === 'escape') {
      handleAction(onEscape, selectItems)
    }
  }

  return (
    <>
      <Button
        trailingAction={variant === 'overlay' ? TriangleDownIcon : null}
        ref={btn}
        variant="default"
        onClick={() => setOpen(!open)}
        aria-haspopup="dialog"
        aria-expanded={open}
        {...buttonProps}
      >
        {renderText
          ? renderText()
          : `${label}${!selectedItems.length ? '' : `: ${selectedItems.map(item => item.label).join(', ')}`}`}
      </Button>
      <SelectContainer
        headingId={headingId}
        open={open}
        anchorRef={btn}
        onClose={onClose}
        variant={variant}
        dialogProps={dialogProps}
        title={title}
        selectSave={selectSave}
        selectCancel={selectCancel}
        footerButtons={footerButtons}
      >
        <div data-container={variant} className={styles.Wrapper}>
          {variant === 'overlay' ? <SelectHeader id={headingId} title={title} onClose={selectCancel} /> : null}
          <SelectBody
            selectionVariant={selectionVariant}
            items={selectable && staticItems ? staticItems : items}
            onSelect={
              selectionVariant === 'single' && !onSave && !selectable
                ? selection => {
                    onSelect?.(selection)
                    setOpen(false)
                  }
                : onSelect
            }
            controlled={selectable ? handleControlledItems : undefined}
            ref={focusTarget === 'first-item' ? firstItem : null}
          />
          {onSave && variant !== 'modal' ? (
            <SelectFooter onSave={selectSave} onCancel={selectCancel} footerButtons={footerButtons} />
          ) : null}
        </div>
      </SelectContainer>
    </>
  )
}

function SelectContainer({
  open,
  anchorRef: btn,
  headingId,
  focusTarget,
  firstItem,
  onClose,
  children,
  variant,
  dialogProps,
  title,
  selectSave,
  selectCancel,
  footerButtons,
}: {
  open: boolean
  anchorRef: React.RefObject<HTMLButtonElement>
  headingId: string
  focusTarget?: 'first-item' | 'first-target'
  firstItem?: React.RefObject<HTMLLIElement>
  onClose: (gesture: string) => void
  children: React.ReactNode
  variant?: 'overlay' | 'modal'
  dialogProps?: SimpleSelectDialogProps
  title?: string
  selectSave?: () => void
  selectCancel?: () => void
  footerButtons?: FooterButtons[]
}) {
  return (
    <>
      {variant === 'overlay' ? (
        <AnchoredOverlay
          open={open}
          anchorRef={btn}
          renderAnchor={null}
          overlayProps={{
            role: 'dialog',
            'aria-labelledby': headingId,
          }}
          focusZoneSettings={{
            disabled: true,
          }}
          focusTrapSettings={{initialFocusRef: focusTarget === 'first-item' ? firstItem : undefined}}
          onClose={onClose}
        >
          {children}
        </AnchoredOverlay>
      ) : (
        <>
          {open ? (
            <Dialog
              renderBody={() => <Dialog.Body className={styles.DialogBody}>{children}</Dialog.Body>}
              width="large"
              onClose={onClose}
              title={title}
              renderFooter={() => (
                <SelectFooter onSave={selectSave} onCancel={selectCancel} footerButtons={footerButtons} />
              )}
              position={{
                narrow: 'fullscreen',
                regular: 'center',
              }}
              {...dialogProps}
            />
          ) : null}
        </>
      )}
    </>
  )
}

type SelectHeaderProps = {
  id: string
  title?: string
  onClose: () => void
}

function SelectHeader({id, title = 'Select an item', onClose}: SelectHeaderProps) {
  return (
    <div className={styles.Header}>
      <Heading id={id} as="h1" className={styles.Title}>
        {title}
      </Heading>
      <IconButton icon={XIcon} aria-label="Close" variant="invisible" onClick={onClose} />
    </div>
  )
}

interface SelectBodyProps {
  selectionVariant: 'single' | 'multiple'
  items: Items[]
  onSelect?: (selectedItem: Items, items?: Items[]) => void
  controlled?: (items: Items[]) => void
}

const SelectBody = forwardRef<HTMLLIElement, SelectBodyProps>(
  ({selectionVariant, items, onSelect, controlled}, ref) => {
    const [selectedItems, setSelectedItems] = useState<Items[]>([])
    const hasGroupId = items.find(item => item.groupId !== undefined)
    useEffect(() => {
      // We need to initialize selectedItems only once -
      // as we only want to take from the state set within this component (`SelectBody`)
      setSelectedItems(items.filter(item => item.selected))
    }, [items])

    const groups = hasGroupId
      ? items.reduce(
          (options, item) => {
            if (item.groupId !== undefined) {
              options[item.groupId] = options[item.groupId] || []
              if (options[item.groupId]) (options[item.groupId] as Items[]).push(item)
            }
            return options
          },
          {} as {[key: number]: Items[]},
        )
      : null

    const itemsWithoutGroup = items.filter(item => item.groupId === undefined)
    const groupCollection = groups && Object.entries(groups)

    const onSelectToggle = (selectedItem: Items) => {
      const {id} = selectedItem
      if (onSelect) onSelect(selectedItem)

      if (controlled) {
        const isSelected = selectedItems.find(item => item.id === id)
        if (!isSelected) {
          const itemSelected = selectionVariant === 'multiple' ? [...selectedItems, selectedItem] : [selectedItem]
          setSelectedItems(itemSelected)
          controlled(itemSelected)
        } else {
          const refreshedItems = selectedItems.filter(item => item.id !== id)
          setSelectedItems(refreshedItems)
          controlled(refreshedItems)
        }
      }
    }

    return (
      <div>
        <ActionList role="listbox" selectionVariant={selectionVariant} aria-label="Selection">
          {groups ? (
            <>
              {groupCollection
                ? groupCollection.map(([groupId, groupItems], index) => (
                    <React.Fragment key={groupId}>
                      <ActionList.Group key={groupId} aria-label={groupItems[0]?.groupTitle || `Group ${groupId}`}>
                        {groupItems.map(
                          (
                            {label, id, selected, description, descriptionVariant, renderItem, renderDescription},
                            itemIndex,
                          ) => (
                            <SelectItem
                              key={id}
                              label={label}
                              id={id}
                              description={description}
                              descriptionVariant={descriptionVariant}
                              // TODO: This iterates through all items; we should probably use a map or object instead
                              selected={!controlled ? Boolean(selected) : selectedItems.some(item => item.id === id)}
                              onSelect={() => {
                                onSelectToggle({label, id, selected, description, descriptionVariant})
                              }}
                              ref={itemIndex === 0 && index === 0 ? ref : undefined}
                              renderItem={renderItem}
                              renderDescription={renderDescription}
                            />
                          ),
                        )}
                      </ActionList.Group>
                      {groupCollection.length > 1 && index !== groupCollection.length - 1 ? (
                        <ActionList.Divider />
                      ) : null}
                    </React.Fragment>
                  ))
                : null}

              {itemsWithoutGroup.map(
                ({label, id, selected, description, descriptionVariant, renderItem, renderDescription}) => (
                  <SelectItem
                    key={id}
                    label={label}
                    id={id}
                    description={description}
                    descriptionVariant={descriptionVariant}
                    selected={!controlled ? Boolean(selected) : selectedItems.some(item => item.id === id)}
                    onSelect={() => {
                      onSelectToggle({label, id, selected, description, descriptionVariant})
                    }}
                    renderItem={renderItem}
                    renderDescription={renderDescription}
                  />
                ),
              )}
            </>
          ) : (
            <>
              {items.map(
                (
                  {label, id, selected, className, description, descriptionVariant, renderItem, renderDescription},
                  index,
                ) => (
                  <SelectItem
                    key={id}
                    label={label}
                    id={id}
                    description={description}
                    descriptionVariant={descriptionVariant}
                    selected={!controlled ? Boolean(selected) : selectedItems.some(item => item.id === id)}
                    onSelect={() => {
                      onSelectToggle({label, id, selected, description, descriptionVariant})
                    }}
                    className={className}
                    renderItem={renderItem}
                    renderDescription={renderDescription}
                    ref={index === 0 ? ref : null}
                  />
                ),
              )}
            </>
          )}
        </ActionList>
      </div>
    )
  },
)

SelectBody.displayName = 'SelectBody'

const SelectItem = forwardRef<HTMLLIElement, SelectItemProps>((props, ref) => {
  if (props.renderItem) {
    return props.renderItem(props)
  }

  const {label, id, selected, description, descriptionVariant, onSelect, renderDescription, className} = props

  return (
    <ActionList.Item
      key={id}
      role="option"
      onSelect={() => {
        onSelect({label, id, selected, description, descriptionVariant})
      }}
      selected={selected}
      ref={ref}
      className={className}
    >
      {label}
      {(description || renderDescription) && (
        <ActionList.Description variant={descriptionVariant}>
          {renderDescription ? renderDescription() : description}
        </ActionList.Description>
      )}
    </ActionList.Item>
  )
})

SelectItem.displayName = 'SelectItem'

type SelectFooterBtns = {
  save?: FooterButtons
  cancel?: FooterButtons
  supplementary: FooterButtons[]
}

function SelectFooter({
  footerButtons,
  onSave,
  onCancel,
}: {
  footerButtons?: FooterButtons[]
  onSave?: () => void
  onCancel?: () => void
}) {
  const buttons = footerButtons?.reduce<SelectFooterBtns>(
    (acc, button) => {
      if (button?.action === 'save' || button?.action === 'cancel') {
        acc[button.action] = button
      } else {
        acc.supplementary.push(button)
      }
      return acc
    },
    {save: undefined, cancel: undefined, supplementary: []},
  )

  return (
    <div className={styles.Footer}>
      <div className={styles.FooterContent}>
        {footerButtons
          ? buttons?.supplementary.map(({variant, content, action, ...rest}) => (
              <Button key={content} variant={variant || 'default'} {...rest}>
                {content}
              </Button>
            ))
          : null}
      </div>
      <div className={styles.FooterActions}>
        <Button onClick={onCancel} {...buttons?.cancel}>
          {buttons?.cancel?.content || 'Cancel'}
        </Button>
        <Button variant="primary" onClick={onSave} {...buttons?.save}>
          {buttons?.save?.content || 'Save'}
        </Button>
      </div>
    </div>
  )
}

try{ SimpleSelect.displayName ||= 'SimpleSelect' } catch {}
try{ SelectContainer.displayName ||= 'SelectContainer' } catch {}
try{ SelectHeader.displayName ||= 'SelectHeader' } catch {}
try{ SelectFooter.displayName ||= 'SelectFooter' } catch {}